"""High-density unlock and transfer record page."""

from .theme import theme_head
from .ui_common import sidebar_html


def unlocks_html() -> str:
    return r'''<!doctype html><html lang="zh-CN"><head>''' + theme_head() + r'''<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>解锁记录 · 115娱乐中心</title><style>
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 72% 3%,var(--accent-soft) 0,var(--bg-deep) 40%,var(--bg-primary) 100%);color:var(--text);font:14px system-ui,-apple-system,"Microsoft YaHei",sans-serif}.shell{display:grid;grid-template-columns:235px minmax(0,1fr);min-height:100vh}.side{background:var(--sidebar-bg);border-right:1px solid var(--line);padding:18px 10px}.logo{font-size:21px;font-weight:800;color:var(--accent-primary);padding:7px 12px 28px}.group{font-size:11px;color:var(--text-muted);margin:14px 10px 7px;border-bottom:1px solid var(--border-secondary);padding-bottom:8px}.nav{display:block;color:var(--text-secondary);text-decoration:none;padding:13px 16px;margin:3px 0;border-radius:12px;font-weight:700}.nav:hover,.nav.active{background:var(--hover-bg);color:var(--accent-primary)}.main{min-width:0}.top{height:64px;display:flex;align-items:center;padding:0 28px;background:var(--bg-secondary);border-bottom:1px solid var(--line)}.heading{font-size:22px;font-weight:800;color:var(--accent-primary)}.refresh{margin-left:auto;border:1px solid var(--accent-secondary);background:var(--button-secondary-bg);color:var(--accent-primary);border-radius:10px;padding:9px 18px}.wrap{max-width:1540px;margin:auto;padding:22px 26px}.filters{display:grid;grid-template-columns:minmax(220px,1fr) 160px 150px 170px auto auto;gap:10px;padding:14px;background:var(--panel);border:1px solid var(--line);border-radius:14px;margin-bottom:12px}.control{height:43px;background:var(--input-bg);border:1px solid var(--input-border);border-radius:9px;color:var(--text-primary);padding:0 12px}.btn{border:1px solid var(--accent-primary);background:var(--button-secondary-bg);color:var(--accent-primary);border-radius:9px;padding:0 14px}.btn.red{border-color:var(--danger);color:var(--danger)}.panel{background:var(--card-bg);border:1px solid var(--line);border-radius:15px;overflow:hidden;min-height:600px}.thead,.row{display:grid;grid-template-columns:34px minmax(190px,1.1fr) 150px 65px minmax(240px,1.4fr) 105px 115px minmax(170px,1fr) 120px 85px;align-items:center;gap:10px;padding:13px 16px}.thead{background:var(--surface-secondary);color:var(--text-muted);border-bottom:1px solid var(--line)}.row{min-height:91px;border-bottom:1px solid var(--border-secondary)}.row:hover{background:var(--surface-hover)}.title{font-weight:800;color:var(--text-primary)}.sub{color:var(--text-muted);font-size:12px;margin-top:5px;line-height:1.45}.points{color:var(--accent-secondary);font-weight:800}.tag{display:inline-block;padding:5px 8px;border-radius:12px;background:var(--success-bg);color:var(--success);font-size:12px}.tag.bad{background:var(--danger-bg);color:var(--danger)}.tag.wait{background:var(--warning-bg);color:var(--warning)}.path{word-break:break-all;color:var(--text-secondary)}.action{border:1px solid var(--accent-secondary);background:var(--accent-soft);color:var(--accent-primary);border-radius:8px;padding:7px;cursor:pointer}.pager{display:flex;justify-content:center;align-items:center;gap:12px;padding:18px}.pager button{border:1px solid var(--accent-secondary);background:var(--button-secondary-bg);color:var(--accent-primary);border-radius:50%;width:38px;height:38px}.pager button:disabled{opacity:.3}.state{text-align:center;padding:120px 20px;color:var(--text-muted)}.state h2{color:var(--text-primary)}.skeleton{height:90px;margin:0 16px;border-bottom:1px solid var(--border-secondary);background:linear-gradient(90deg,var(--skeleton-a) 25%,var(--skeleton-b) 38%,var(--skeleton-a) 63%);background-size:400% 100%;animation:s 1.2s infinite}@keyframes s{to{background-position:-100% 0}}.modal{position:fixed;inset:0;background:var(--overlay-bg);display:none;place-items:center;z-index:50}.modal.open{display:grid}.dialog{width:min(760px,94vw);max-height:85vh;overflow:auto;background:var(--modal-bg);border:1px solid var(--accent-secondary);border-radius:16px;padding:22px}.close{float:right;background:none;border:0;color:var(--text-primary);font-size:25px}.entry{border-top:1px solid var(--border-secondary);padding:10px 0;color:var(--text-secondary)}.toast{position:fixed;right:24px;bottom:24px;padding:13px 17px;border-radius:10px;background:var(--success-bg);border:1px solid var(--ok-line);color:var(--success);display:none}.toast.bad{background:var(--danger-bg);border-color:var(--bad-line);color:var(--danger)}
@media(max-width:1250px){.optional{display:none}.thead,.row{grid-template-columns:34px minmax(170px,1fr) 130px 60px minmax(210px,1.3fr) 100px 110px 80px}.filters{grid-template-columns:1fr 140px 140px 150px auto auto}}
@media(max-width:850px){.shell{display:block}.side{display:none}.wrap{padding:12px}.filters{grid-template-columns:1fr 1fr}.filters input{grid-column:1/-1}.thead{display:none}.panel{border:0;background:none}.row{display:grid;grid-template-columns:26px 1fr auto;border:1px solid var(--line);border-radius:12px;margin-bottom:9px;background:var(--panel)}.row>div{display:block}.row .resource{grid-column:2}.row .action{grid-column:3;grid-row:1/4}}
</style></head><body><div class="shell">''' + sidebar_html("unlocks") + '''<main class="main"><header class="top"><div class="heading">🔓 解锁记录</div><button class="refresh" id="refresh">↻ 刷新</button></header><section class="wrap"><div class="filters"><input id="search" class="control" placeholder="⌕ 搜索名称"><select id="action" class="control"><option value="">全部解锁类型</option><option value="资源解锁">资源解锁</option><option value="网盘分享">网盘分享</option></select><select id="status" class="control"><option value="">全部解锁状态</option><option value="unlocked">已解锁</option><option value="pending">待解锁</option><option value="failed">解锁失败</option></select><select id="transfer" class="control"><option value="">全部转存状态</option><option value="success">转存成功</option><option value="pending">待转存</option><option value="processing">转存中</option><option value="failed">转存失败</option></select><button class="btn" id="reset">重置</button><button class="btn red" id="batch">批量删除</button></div><section class="panel"><div class="thead"><div><input type="checkbox" id="all"></div><div>影片</div><div>时间与动作</div><div>积分</div><div>资源</div><div>解锁类型</div><div>解锁 / 转存</div><div class="optional">保存路径</div><div class="optional">处理结果</div><div>操作</div></div><div id="list"></div><div class="pager" id="pager"></div></section></section></main></div><div class="modal" id="modal"><div class="dialog"><button id="close" class="close">×</button><div id="detail"></div></div></div><div class="toast" id="toast"></div><script>
const S={page:1,page_size:15,search:'',action:'',unlock_status:'',transfer_status:''};const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),dt=v=>v?new Date(Number(v)*1000).toLocaleString('zh-CN',{hour12:false}):'-';function ul(v){return v==='unlocked'?['已解锁','']:v==='failed'?['解锁失败','bad']:['待解锁','wait']}function ts(v){return v==='success'?['转存成功','']:v==='failed'?['转存失败','bad']:v==='processing'?['转存中','wait']:['待转存','wait']}function row(x){const a=ul(x.unlock_status||x.status),p=ts(x.transfer_status||x.processing_status);return `<article class="row"><div><input class="pick" type="checkbox" value="${x.id}"></div><div><div class="title">${esc(x.name)}</div><div class="sub">${esc(x.media_type||'影视')} ${x.tmdb_id?'· TMDB '+x.tmdb_id:''}</div></div><div>${dt(x.created_at)}<div class="sub">${esc(x.action||'资源解锁')}</div></div><div class="points">◇ ${x.points||0}</div><div class="resource"><div>${esc(x.resolution||'')} ${esc(x.quality||'')} · ${esc(x.source_type||'115网盘')} · ${esc(x.size||'大小未知')}</div><div class="sub">${x.uploader?'· 分享者 '+esc(x.uploader):''}</div></div><div>${esc(x.action||'资源解锁')}</div><div><span class="tag ${a[1]}">${a[0]}</span><div class="sub"><span class="tag ${p[1]}">${p[0]}</span></div></div><div class="path optional">${esc(x.save_path||'尚未设置')}</div><div class="optional">${esc(x.error||'-')}</div><button class="action" data-id="${x.id}">${x.unlock_status==='failed'?'重试':x.transfer_status==='failed'?'重试转存':'详情'}</button></article>`}
function skeleton(){return '<div class="skeleton"></div>'.repeat(6)}async function load(){ $('#list').innerHTML=skeleton();const q=new URLSearchParams();for(const[k,v]of Object.entries(S))if(v)q.set(k,v);try{const r=await fetch('/api/web/unlocks?'+q),d=await r.json();if(!r.ok)throw Error(apiMsg(d, '加载失败'));if(!d.items.length)$('#list').innerHTML='<div class="state"><h2>暂无解锁记录</h2><p>解锁或转存资源后，记录会显示在这里。</p></div>';else{$('#list').innerHTML=d.items.map(row).join('');document.querySelectorAll('.action').forEach(b=>b.onclick=()=>detail(+b.dataset.id))}$('#pager').innerHTML=`<button id="prev" ${d.page<=1?'disabled':''}>‹</button><span>第 ${d.page} / ${d.total_pages} 页 · 共 ${d.total} 条</span><button id="next" ${!d.has_more?'disabled':''}>›</button>`;$('#prev').onclick=()=>{S.page--;load()};$('#next').onclick=()=>{S.page++;load()}}catch(e){$('#list').innerHTML=`<div class="state"><h2>解锁记录加载失败</h2><p>${esc(e.message)}</p></div>`}}
async function detail(id){const r=await fetch('/api/web/unlocks/'+id),d=await r.json();if(!r.ok)return toast(apiMsg(d, '详情失败'),true);const x=d.item;$('#detail').innerHTML=`<h2>${esc(x.name)}</h2><div class="entry">资源标识：${esc(x.slug)}</div><div class="entry">解锁状态：${esc(ul(x.unlock_status||x.status)[0])}</div><div class="entry">转存状态：${esc(ts(x.transfer_status||x.processing_status)[0])}</div><div class="entry">115链接：${x.share_url?`<a href="${esc(x.share_url)}" target="_blank" rel="noreferrer">${esc(x.share_url)}</a>`:'-'}</div><div class="entry">保存路径：${esc(x.save_path||'-')}</div>${x.error?`<div class="entry">失败原因：${esc(x.error)}</div><button class="action" onclick="retry(${x.id})">重试转存</button>`:''}`;$('#modal').classList.add('open')}async function retry(id){const r=await fetch('/api/web/unlocks/'+id+'/retry',{method:'POST'}),d=await r.json();if(!r.ok)return toast(apiMsg(d, '重试失败'),true);toast('重试成功');$('#modal').classList.remove('open');load()}
async function remove(){const ids=[...document.querySelectorAll('.pick:checked')].map(x=>+x.value);if(!ids.length)return toast('请先选择记录',true);if(!confirm(`确认删除选中的 ${ids.length} 条记录吗？\n只删除日志，不会删除115文件。`))return;const r=await fetch('/api/web/unlocks',{method:'DELETE',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids})}),d=await r.json();if(!r.ok)return toast(apiMsg(d, '删除失败'),true);toast(`已删除 ${d.deleted} 条记录，115文件未删除`);load()}function toast(m,b=false){const t=$('#toast');t.textContent=m;t.className='toast'+(b?' bad':'');t.style.display='block';setTimeout(()=>t.style.display='none',3200)}let timer;$('#search').oninput=e=>{clearTimeout(timer);timer=setTimeout(()=>{S.search=e.target.value;S.page=1;load()},350)};for(const [id,key] of [['action','action'],['status','unlock_status'],['transfer','transfer_status']])$('#'+id).onchange=e=>{S[key]=e.target.value;S.page=1;load()};$('#reset').onclick=()=>{Object.assign(S,{page:1,search:'',action:'',unlock_status:'',transfer_status:''});['search','action','status','transfer'].forEach(id=>$('#'+id).value='');load()};$('#all').onchange=e=>document.querySelectorAll('.pick').forEach(x=>x.checked=e.target.checked);$('#batch').onclick=remove;$('#refresh').onclick=load;$('#close').onclick=()=>$('#modal').classList.remove('open');load();
</script></body></html>'''
